process::WFP Seed Assumptions.PrologProcedure:
#Region Seed WFP Assumptions — global planning drivers, per Period x Version x Entity
# Idempotent. Written at the LEAF entities only (Group is a consolidation and
# rates don't sum); rules read assumptions at the position's Home Entity (a leaf).
# Same values across all periods/versions/entities for now — edit per cell after
# where a driver should vary (e.g. Merit % by year).
cCube = 'WFP Assumptions';
cPer  = 'WFP Period';
nPcount = DIMSIZ( cPer );

# measure ; value
vM =
'Merit Increase %;0.03~' |
'Promotion Budget %;0.01~' |
'Inflation %;0.025~' |
'Actuals Cutoff Index;15~' |
'Vacancy Allowance %;0.10~' |
'Standard FTE Hours;160~' |
'Bonus Pool %;0.10~' |
'Employer Oncost Fallback %;0.15~';

vVers = 'Budget|Working|Forecast|';
vEnts = 'UK Ltd|US Inc|NZ Ltd|';

nP = 1;
WHILE( nP <= nPcount );
   vPer = DIMNM( cPer, nP );
   IF( DTYPE( cPer, vPer ) @= 'N' & LONG( vPer ) = 7 );
      vVl = vVers;
      WHILE( SCAN( '|', vVl ) > 1 );
         nS = SCAN( '|', vVl ); vVer = SUBST( vVl, 1, nS - 1 ); vVl = SUBST( vVl, nS + 1, LONG( vVl ) - nS );
         vEl = vEnts;
         WHILE( SCAN( '|', vEl ) > 1 );
            nS = SCAN( '|', vEl ); vEnt = SUBST( vEl, 1, nS - 1 ); vEl = SUBST( vEl, nS + 1, LONG( vEl ) - nS );
            vRows = vM;
            WHILE( SCAN( '~', vRows ) > 1 );
               nS = SCAN( '~', vRows ); vRec = SUBST( vRows, 1, nS - 1 ) | ';'; vRows = SUBST( vRows, nS + 1, LONG( vRows ) - nS );
               nS = SCAN( ';', vRec ); vMeas = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
               nS = SCAN( ';', vRec ); nVal  = NUMBR( SUBST( vRec, 1, nS - 1 ) );
               CellPutN( nVal, cCube, vPer, vVer, vEnt, vMeas );
            END;
         END;
      END;
   ENDIF;
   nP = nP + 1;
END;

process::WFP Seed Workforce Input.PrologProcedure:
#Region Seed Workforce Input — FTE + Base Salary per active month (Period, Version, Position, Measure)
# Budget + Working = seed defaults. Actual = same as Working, EXCEPT a real
# in-year raise: EXEC-001 to 220,000 for 2026-01..2026-03 (closed months) so the
# Forecast blend (Actual for <= Actuals Cutoff Index, else Working) is visible.
cCube = 'WFP Workforce Input';
cPos  = 'WFP Position';
cPer  = 'WFP Period';

nPosCount = DIMSIZ( cPos );
nPerCount = DIMSIZ( cPer );

nI = 1;
WHILE( nI <= nPosCount );
   vPos = DIMNM( cPos, nI );
   IF( DTYPE( cPos, vPos ) @= 'N' );
      nFTE = ATTRN( cPos, vPos, 'FTE' );
      nSal = ATTRN( cPos, vPos, 'Seed Base Salary' );
      vStartPd = ATTRS( cPos, vPos, 'Start Period' );
      vEndPd = ATTRS( cPos, vPos, 'End Period' );
      nStartIdx = ATTRN( cPer, vStartPd, 'Period Index' );
      nEndIdx = IF( vEndPd @= '', 999, ATTRN( cPer, vEndPd, 'Period Index' ) );

      nP = 1;
      WHILE( nP <= nPerCount );
         vPer = DIMNM( cPer, nP );
         IF( DTYPE( cPer, vPer ) @= 'N' );
            nPidx = ATTRN( cPer, vPer, 'Period Index' );
            IF( nPidx >= nStartIdx & nPidx <= nEndIdx );
               CellPutN( nFTE, cCube, vPer, 'Budget',   vPos, 'FTE' );
               CellPutN( nSal, cCube, vPer, 'Budget',   vPos, 'Base Salary' );
               CellPutN( nFTE, cCube, vPer, 'Working',  vPos, 'FTE' );
               CellPutN( nSal, cCube, vPer, 'Working',  vPos, 'Base Salary' );

               # Actual: mirrors Working, with the EXEC-001 raise for closed months
               nActSal = nSal;
               IF( vPos @= 'EXEC-001' & nPidx >= 13 & nPidx <= 15 );
                  nActSal = 220000;
               ENDIF;
               CellPutN( nFTE,    cCube, vPer, 'Actual', vPos, 'FTE' );
               CellPutN( nActSal, cCube, vPer, 'Actual', vPos, 'Base Salary' );
            ENDIF;
         ENDIF;
         nP = nP + 1;
      END;
   ENDIF;
   nI = nI + 1;
END;

