process::WFP Seed Workforce Input.PrologProcedure:
#Region Seed Workforce Input — FTE + Base Salary + One-Time per active month
# Budget = flat seed (the approved/frozen plan). Working = seed with the merit +
# promotion uplift applied from Merit Review Index. Actual = flat, plus the real
# EXEC-001 Jan-Mar raise. One-Time: a sample CS-001 retention payment in 2026-06.
cCube = 'WFP Workforce Input';
cPos  = 'WFP Position';
cPer  = 'WFP Period';
cAsm  = 'WFP Assumptions';

nPosCount = DIMSIZ( cPos );
nPerCount = DIMSIZ( cPer );

nI = 1;
WHILE( nI <= nPosCount );
   vPos = DIMNM( cPos, nI );
   IF( DTYPE( cPos, vPos ) @= 'N' );
      nFTE = ATTRN( cPos, vPos, 'FTE' );
      nSal = ATTRN( cPos, vPos, 'Seed Base Salary' );
      vHome = ATTRS( cPos, vPos, 'Home Entity' );
      vStartPd = ATTRS( cPos, vPos, 'Start Period' );
      vEndPd = ATTRS( cPos, vPos, 'End Period' );
      nStartIdx = ATTRN( cPer, vStartPd, 'Period Index' );
      nEndIdx = IF( vEndPd @= '', 999, ATTRN( cPer, vEndPd, 'Period Index' ) );

      # comp-action assumptions (flat across periods; read at the home entity)
      nMeritIdx = CellGetN( cAsm, '2026-01', 'Working', vHome, 'Merit Review Index' );
      nUplift   = CellGetN( cAsm, '2026-01', 'Working', vHome, 'Merit Increase %' )
                + CellGetN( cAsm, '2026-01', 'Working', vHome, 'Promotion Budget %' );

      nP = 1;
      WHILE( nP <= nPerCount );
         vPer = DIMNM( cPer, nP );
         IF( DTYPE( cPer, vPer ) @= 'N' );
            nPidx = ATTRN( cPer, vPer, 'Period Index' );
            IF( nPidx >= nStartIdx & nPidx <= nEndIdx );
               CellPutN( nFTE, cCube, vPer, 'Budget',  vPos, 'FTE' );
               CellPutN( nSal, cCube, vPer, 'Budget',  vPos, 'Base Salary' );
               CellPutN( nFTE, cCube, vPer, 'Working', vPos, 'FTE' );

               # Working salary: flat until the review month, then uplifted
               nWkSal = nSal;
               IF( nPidx >= nMeritIdx );
                  nWkSal = nSal * ( 1 + nUplift );
               ENDIF;
               CellPutN( nWkSal, cCube, vPer, 'Working', vPos, 'Base Salary' );

               # Actual: mirrors flat seed, with the EXEC-001 raise for closed months
               nActSal = nSal;
               IF( vPos @= 'EXEC-001' & nPidx >= 13 & nPidx <= 15 );
                  nActSal = 220000;
               ENDIF;
               CellPutN( nFTE,    cCube, vPer, 'Actual', vPos, 'FTE' );
               CellPutN( nActSal, cCube, vPer, 'Actual', vPos, 'Base Salary' );
            ENDIF;
         ENDIF;
         nP = nP + 1;
      END;
   ENDIF;
   nI = nI + 1;
END;

# Sample one-time payment: CS-001 retention, 15,000 in 2026-06 (Budget + Working)
CellPutN( 15000, cCube, '2026-06', 'Budget',  'CS-001', 'One-Time Amount' );
CellPutN( 15000, cCube, '2026-06', 'Working', 'CS-001', 'One-Time Amount' );
